graphql.query:
query GetUser {
  user {
    ...SegmentsModules
    id
    permissions {
      key
    }
    customer {
      id
      name
      labels {
        id
      }
      isGlobalTranslationEnabled
    }
    notificationBrandId
  }
}

fragment SegmentsModules on User {
  segments {
    segment {
      id
      useCustomModulesOrder
      name
      imageUrl
      useTonality
      userTranslationEnabled
      useKeyNamedEntities
    }
    order
    useCustomSegmentModules
    modules {
      ...UserSegmentModule
    }
    subscriptions {
      ...Subscription
    }
  }
  favorites {
    ...UserFavorites
  }
}

fragment UserSegmentModule on UserSegmentModule {
  module {
    id
    key
  }
}

fragment Subscription on UserSegmentSubscription {
  adType {
    key
  }
  channels
}

fragment UserFavorites on UserFavorite {
  entityType
  segment {
    id
  }
  payload {
    ... on PersonNamedEntity {
      id
    }
    ... on OrganizationNamedEntity {
      id
    }
    ... on GeoNamedEntity {
      id
    }
    ... on Module {
      id
      key
    }
    ... on MassMediaUserFeed {
      id
    }
    ... on SocMediaUserFeed {
      id
    }
  }
}

